/* =========================================================
   WebHarbor — project page
   Same "Maritime Precision" system as assets/style.css (guides):
   cream paper, navy accent, teal and warm highlights.
   ========================================================= */

:root {
  --bg:          #F6F5F0;
  --bg-alt:      #EDECE6;
  --surface:     #FFFFFF;
  --text:        #0C1222;
  --text-soft:   #3D4559;
  --text-muted:  #6B7280;
  --border:      #D6D3C8;
  --border-soft: #E8E5DC;

  --accent:      #1B4B8F;
  --accent-ink:  #0F2E5A;
  --accent-soft: #E8EFF8;
  --teal:        #0D7377;
  --teal-soft:   #E6F5F5;
  --warm:        #C4713B;
  --warm-soft:   #FDF0E6;
  --warn:        #A63D2F;
  --warn-soft:   #FAECE9;
  --code-bg:     #0C1222;

  --serif: "DM Serif Display", Georgia, serif;
  --sans:  "Instrument Sans", system-ui, -apple-system, "Segoe UI", sans-serif;
  --mono:  "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, monospace;

  --shadow-sm: 0 1px 2px rgba(12,18,34,.03), 0 2px 6px rgba(12,18,34,.05);
  --shadow-md: 0 4px 12px rgba(12,18,34,.06), 0 2px 4px rgba(12,18,34,.04);
  --shadow-lg: 0 12px 40px rgba(12,18,34,.10), 0 4px 12px rgba(12,18,34,.05);
  --shadow-xl: 0 20px 60px rgba(12,18,34,.14);

  --radius:    16px;
  --radius-sm: 10px;
  --radius-lg: 24px;
  --max: 1248px;

  --tile-w: 248px;
  --tile-h: 155px;
  --tile-gap: 14px;
}

*, *::before, *::after { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 84px; -webkit-text-size-adjust: 100%; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--sans);
  font-size: 16.5px;
  line-height: 1.65;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  text-wrap: pretty;
}
h1, h2, h3 { text-wrap: balance; }
img { max-width: 100%; display: block; }
a { color: var(--accent); text-decoration: none; }
a:hover { text-decoration: underline; text-underline-offset: 3px; text-decoration-thickness: 1.5px; }
button { font: inherit; color: inherit; }
code {
  font-family: var(--mono); font-size: .88em; color: var(--text);
  background: var(--bg-alt); border: 1px solid var(--border-soft);
  padding: .12em .42em; border-radius: 5px;
}
:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; border-radius: 6px; }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.wrap { max-width: var(--max); margin: 0 auto; padding: 0 36px; }

/* ---------------- NAV (as in style.css) ---------------- */
.nav {
  position: sticky; top: 0; z-index: 50;
  background: rgba(246,245,240,.88);
  -webkit-backdrop-filter: saturate(180%) blur(14px);
  backdrop-filter: saturate(180%) blur(14px);
  border-bottom: 1px solid var(--border-soft);
}
.nav .wrap { display: flex; align-items: center; gap: 24px; padding-top: 14px; padding-bottom: 14px; max-width: 1400px; }
.brand { display: inline-flex; align-items: center; gap: 10px; font-family: var(--serif); font-size: 1.15rem; color: var(--text); letter-spacing: .01em; }
.brand:hover { text-decoration: none; }
.brand-mark { color: var(--accent); font-size: 1.25rem; }
.nav-links { display: flex; gap: 24px; margin-left: auto; align-items: center; font-size: .875rem; font-weight: 600; letter-spacing: .01em; }
.nav-links a:not(.nav-cta) { color: var(--text-muted); position: relative; transition: color .2s; }
.nav-links a:not(.nav-cta):hover { color: var(--accent); text-decoration: none; }
.nav-links a:not(.nav-cta)::after {
  content: ""; position: absolute; left: 0; bottom: -4px; width: 0; height: 1.5px; background: var(--accent); transition: width .25s ease;
}
.nav-links a:not(.nav-cta):hover::after { width: 100%; }
.nav-ctas { display: flex; gap: 10px; margin-left: 8px; }
.nav-cta {
  font-size: .875rem; font-weight: 700; padding: 8px 15px; border-radius: 8px;
  background: var(--accent); color: #fff; border: 1.5px solid var(--accent);
  transition: background .2s, transform .15s, border-color .2s, color .2s;
}
.nav-cta:hover { background: var(--accent-ink); border-color: var(--accent-ink); text-decoration: none; transform: translateY(-1px); }
.nav-cta.ghost { background: transparent; color: var(--accent); }
.nav-cta.ghost:hover { background: var(--accent-soft); color: var(--accent-ink); }
