            var c = arr[(Math.random() * arr.length) | 0];
  padding: 0; border: 1px solid var(--border); border-radius: 10px;
  background-color: var(--bg-alt);
  background-position: 0% 0;
  background-size: 600% 100%;
  background-repeat: no-repeat;
  cursor: pointer;
  overflow: hidden;
  box-shadow: var(--shadow-md);
  transition: transform .35s cubic-bezier(.2,.8,.2,1), box-shadow .35s ease, border-color .35s;
}
@keyframes frames { from { background-position: 0% 0; } to { background-position: 120% 0; } }
.tile-label {
  position: absolute; left: 0; right: 0; bottom: 0;
  padding: 10px 12px;
  display: flex; align-items: baseline; gap: 8px;
  font-size: 13px; font-weight: 700; color: var(--text); text-align: left;
  background: rgba(255,255,255,.94);
  border-top: 1px solid var(--border-soft);
  opacity: 0; transform: translateY(100%);
  transition: opacity .25s ease, transform .25s ease;
}
.tile-label em {
  font-style: normal; font-family: var(--mono); font-size: 11px; font-weight: 500; margin-left: auto;
  color: var(--accent); background: var(--accent-soft); border: 1px solid rgba(27,75,143,.12); padding: 1px 6px; border-radius: 5px;
}
.tile-play {
  position: absolute; top: 42%; left: 50%; width: 46px; height: 46px; margin: -23px 0 0 -23px;
  border-radius: 50%; background: var(--accent); color: #fff;
  display: grid; place-items: center;
  opacity: 0; transform: scale(.7);
  transition: opacity .25s ease, transform .25s cubic-bezier(.2,.8,.2,1);
  box-shadow: 0 6px 20px rgba(27,75,143,.35);
}
.tile-play::before { content: ""; width: 0; height: 0; margin-left: 4px; border-style: solid; border-width: 8px 0 8px 13px; border-color: transparent transparent transparent currentColor; }
.tile:hover, .tile:focus-visible {
  transform: scale(1.12);
  z-index: 2;
  border-color: var(--accent);
  /* the wide cream spread washes out the rest of the wall */
  box-shadow: 0 0 0 2px var(--accent), 0 0 0 100vmax rgba(246,245,240,.55), var(--shadow-xl);
}
.tile:hover .tile-label, .tile:focus-visible .tile-label,
.tile:hover .tile-play, .tile:focus-visible .tile-play { opacity: 1; transform: none; }

.hero-shade {
  position: absolute; inset: 0; z-index: 1; pointer-events: none;
  background:
    /* the original hero's soft navy / teal / warm glows */
    radial-gradient(ellipse 34% 40% at 30% 34%, rgba(27,75,143,.07), transparent 70%),
    radial-gradient(ellipse 30% 36% at 72% 30%, rgba(13,115,119,.06), transparent 70%),
    radial-gradient(ellipse 30% 30% at 52% 74%, rgba(196,113,59,.05), transparent 70%),
    radial-gradient(ellipse 56% 58% at 50% 50%, rgba(246,245,240,.98) 0%, rgba(246,245,240,.95) 52%, rgba(246,245,240,.55) 78%, rgba(246,245,240,.12) 100%),
    linear-gradient(180deg, rgba(246,245,240,.55) 0%, rgba(246,245,240,.08) 18%, rgba(246,245,240,.08) 80%, rgba(246,245,240,.96) 100%);
}
.hero-content {
  position: relative; z-index: 2;
  pointer-events: none;
  text-align: center;
  padding: 64px 24px 120px;
  max-width: 1180px;
}
.hero-content a, .hero-content button { pointer-events: auto; }
.eyebrow {
  display: inline-flex; align-items: center; gap: 10px;
  font-family: var(--mono); font-size: .79rem; font-weight: 500; letter-spacing: .14em; text-transform: uppercase;
  color: var(--text-muted); background: var(--surface); border: 1px solid var(--border);
  padding: 7px 18px; border-radius: 999px; box-shadow: var(--shadow-sm);
}
.eyebrow .dot { position: relative; width: 8px; height: 8px; border-radius: 50%; background: var(--teal); }
.eyebrow .dot::after { /* transform + opacity only, so the pulse stays on the compositor */
  content: ""; position: absolute; inset: -5px; border-radius: 50%; border: 2px solid var(--teal);
  animation: pulse-dot 2.2s ease-out infinite; will-change: transform, opacity;
}
@keyframes pulse-dot { from { transform: scale(.4); opacity: .55; } 70%, to { transform: scale(1); opacity: 0; } }
.hero-title {
  margin: 28px 0 22px;
  font-family: var(--serif); font-weight: 400;
  font-size: clamp(2.2rem, 4.3vw, 3.7rem); line-height: 1.12; letter-spacing: -.01em;
  color: var(--text); text-wrap: initial;
}
.hero-title .line { white-space: nowrap; }
@media (max-width: 760px) { .hero-title .line { white-space: normal; } .hero-title br { display: none; } }
.accent { color: var(--accent); }
.hero .lede { margin: 0 auto; max-width: 760px; font-size: 1.12rem; line-height: 1.7; color: var(--text-soft); }
.hero .lede a { font-weight: 600; white-space: nowrap; }
h2 a { color: inherit; text-decoration: underline; text-decoration-color: var(--accent); text-decoration-thickness: 2px; text-underline-offset: 6px; }
h2 a:hover { color: var(--accent); }
.hero-actions { margin-top: 32px; display: flex; flex-wrap: wrap; justify-content: center; gap: 12px; }
.btn {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: .9rem; font-weight: 700; letter-spacing: .01em;
  padding: 13px 24px; border-radius: var(--radius-sm);
  border: 1.5px solid transparent; cursor: pointer;
  transition: all .2s ease;
}
.btn:hover { text-decoration: none; transform: translateY(-2px); }
.btn svg { width: 16px; height: 16px; flex: none; }
.btn-primary { background: var(--accent); color: #fff; box-shadow: 0 2px 8px rgba(27,75,143,.25); }
.btn-primary:hover { background: var(--accent-ink); box-shadow: 0 4px 16px rgba(27,75,143,.3); }
.btn-ghost { background: var(--surface); color: var(--text); border-color: var(--border); }
.btn-ghost:hover { border-color: var(--accent); background: var(--accent-soft); color: var(--accent); }
.btn .soon { font-family: var(--mono); font-size: 10.5px; font-weight: 500; letter-spacing: .04em; color: var(--warm); background: var(--warm-soft); padding: 1px 6px; border-radius: 5px; }
.btn[aria-disabled="true"] { cursor: default; }
.btn[aria-disabled="true"]:hover { transform: none; border-color: var(--border); background: var(--surface); color: var(--text); }
.hero-stats { margin: 40px auto 0; display: grid; grid-template-columns: repeat(4, auto); justify-content: center; }
.hero-stats div { padding: 0 28px; border-left: 1px solid var(--border); }
.hero-stats div:first-child { border-left: 0; }
.hero-stats b { display: block; font-family: var(--serif); font-weight: 400; font-size: 2.4rem; line-height: 1.05; color: var(--accent); }
.hero-stats span { font-size: .8rem; color: var(--text-muted); letter-spacing: .02em; }
.hero-hint {
  position: absolute; z-index: 2; left: 50%; bottom: 24px; transform: translateX(-50%);
  display: flex; align-items: center; gap: 10px; white-space: nowrap; margin: 0;
  font-size: 13px; color: var(--text-muted); pointer-events: none;
  padding: 7px 16px; border-radius: 999px; background: var(--surface); border: 1px solid var(--border); box-shadow: var(--shadow-sm);
}
.wall-toggle {
  position: absolute; z-index: 3; right: 22px; bottom: 22px;
  width: 38px; height: 38px; border-radius: 50%;
  display: grid; place-items: center; cursor: pointer;
  background: var(--surface); border: 1px solid var(--border); color: var(--text-soft); box-shadow: var(--shadow-sm);
}
.wall-toggle:hover { color: var(--accent); border-color: var(--accent); }
.wall-toggle svg { width: 14px; height: 14px; }
.wall-toggle .i-play { display: none; }
.hero.is-user-paused .wall-toggle .i-play { display: block; }
.hero.is-user-paused .wall-toggle .i-pause { display: none; }

/* ---------------- SECTIONS (as in style.css) ---------------- */
section { position: relative; }
.section { padding: 100px 0; }
.section + .section { border-top: 1px solid var(--border-soft); }
.section-alt { background: #F1F0EA; }
